int main() {
    int testcase;
    scanf("%d", &testcase);
    while(testcase--){
        int num, num1;
        scanf("%d %d", &num, &num1);
        int arr[num];
        for(int i = 0; i < num; i++)
            scanf("%d", &arr[i]);
        int left = 0;
        int flag = 0;
        for(int i = 0; i < num; i++) {
            if (left + arr[i] < num1) {
                printf("NO %d\n", i + 1);
                flag = 1;
            }
            left = left + arr[i] - num1;
        }
        if (flag == 0) {
